import json


def load_config(path):
    # utf-8-sig 在读的时候自动剥掉开头的 BOM（U+FEFF）
    with open(path, encoding='utf-8-sig') as f:
        return json.load(f)


def dumps_config(cfg):
    # 写的时候也别加 BOM，保持纯净 UTF-8
    return json.dumps(cfg, ensure_ascii=False, indent=2)

def parse_csv_line(line):
    fields = []
    buf = []
    i = 0
    n = len(line)
    in_quotes = False
    while i < n:
        c = line[i]
        if in_quotes:
            if c == '"':
                if i + 1 < n and line[i + 1] == '"':
                    buf.append('"')
                    i += 2
                    continue
                in_quotes = False
            else:
                buf.append(c)
        else:
            if c == '"':
                in_quotes = True
            elif c == ',':
                fields.append(''.join(buf))
                buf = []
            else:
                buf.append(c)
        i += 1
    fields.append(''.join(buf))
    return fields
